#include <iostream>
using namespace std;
float area(float side) {
    return side * side;
}
float perimeter(float side) {
    return 4 * side;
}
int main() {
    float s;
    cout << "Enter side of the square: ";
    cin >> s;
    cout << "Area = " << area(s) << endl;
    cout << "Perimeter = " << perimeter(s) << endl;
    return 0;
}

#include <iostream>
using namespace std;
void checkPrime(int n) {
    if (n < 2) { cout << n << " is neither prime nor composite" << endl; return; }
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) { cout << n << " is a composite number" << endl; return; }
    cout << n << " is a prime number" << endl;
}
int main() {
    int num;
    cout << "Enter a number: ";
    cin >> num;
    checkPrime(num);
    return 0;
}

