called as cout << square(5);

#include <iostream>
using namespace std;
int area(int side) { return side * side; }
int area(int l, int w) { return l * w; }
float area(float r) { return 3.14159 * r * r; }
int main() {
    cout << "Square: " << area(4) << endl;
    cout << "Rectangle: " << area(4, 6) << endl;
    cout << "Circle: " << area(2.5f) << endl;
    return 0;
}
